"""The Neve 1073's mic path (docs/CHAINS_PLAN.md WP11): config/circuits/neve_1073.yaml, GENERATED by
scripts/make_neve_1073.py from Neve's EH10023 / EK20033 / EX/10283 / EX/10284.

It is current with its generator, builds, passes the pre-flight checks at every switch
combination, idles at TR3's trimmed current; SENSITIVITY follows EK20033's labels (the gain
about minus the setting: T3's ratio fitted at -50, the rest the drawings'), LO is ~6 dB hotter
than HI, the top end is -0.5 dB at 20 kHz (T3's leakage fitted) and the output clips at about
+26 dBu.
"""

from __future__ import annotations

import subprocess
import sys

import numpy as np
import pytest

from varimu import preflight
from varimu.circuit import builder, spec
from varimu.config import CONFIG_DIR
from varimu.config import REPO_ROOT as ROOT

NEVE = CONFIG_DIR / "circuits" / "neve_1073.yaml"
FS = 96000.0


@pytest.fixture(scope="module")
def neve():
    return spec.load_circuit(NEVE)


def test_generated_file_is_current():
    r = subprocess.run(
        [sys.executable, str(ROOT / "scripts" / "make_neve_1073.py"), "--check"],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    assert r.returncode == 0, r.stdout + r.stderr


def test_builds_and_every_value_is_sourced(neve):
    for cores in ("ja", "linear"):
        c = builder.build(neve, cores=cores)
        assert (c.text is None) == (cores == "ja")
    assert spec.check_genome_links(neve) == []
    a = builder.build_ir(neve, spec.resolve(neve, {"passive_spread": 1.0, "passive_seed": 3}))
    b = builder.build_ir(neve, spec.resolve(neve))
    moved = sum(e != e0 for e, e0 in zip(a.elements(), b.elements(), strict=True))
    assert moved > 40


def test_preflight_passes(neve):
    assert preflight.check_circuit(neve) == []


def test_sensitivity_rewires(neve):
    def names(**ov):
        return {e.name for e in builder.build_ir(neve, spec.resolve(neve, ov)).elements()}

    assert "RS2A_HI" in names(sensitivity=-70) and "RS2A_HI" not in names(sensitivity=-50)
    assert {"R6S", "R18S"} <= names(sensitivity=-20)
    assert "R29S" in names(sensitivity=-80) and "R30S" in names(sensitivity=-45)
    assert not {"R29S", "R30S"} & names(sensitivity=-70)


def _run(neve, over, f_hz=1000.0, amp=1e-4, dur_s=0.2):
    from varimu.sim import fast

    ir = builder.build_ir(neve, spec.resolve(neve, over), "ja")
    t = np.arange(int(dur_s * FS)) / FS
    x = amp * np.sin(2 * np.pi * f_hz * t) * np.minimum(1.0, t / 0.03)
    v = {k: np.asarray(y) for k, y in fast.run_transient(ir, x).vectors.items()}
    if amp == 0.0:
        return -np.inf, v
    n = int(round(FS / f_hz * max(1, int(0.03 * f_hz))))
    tt, y = t[-n:], v["v(out)"][-n:]
    m = np.column_stack([np.sin(2 * np.pi * f_hz * tt), np.cos(2 * np.pi * f_hz * tt), np.ones(n)])
    a, b, _ = np.linalg.lstsq(m, y, rcond=None)[0]
    return 20 * np.log10(np.hypot(a, b) / amp), v


def test_idle(neve):
    """TR3 at its trimmed ~64 mA (e3 over R7 47), the collector a winding's drop under M."""
    pytest.importorskip("circuitsim")
    _, v = _run(neve, {}, amp=0.0, dur_s=0.05)
    assert v["v(e3)"][-1] / 47.0 == pytest.approx(0.064, rel=0.1)
    assert 20.0 < v["v(bb)"][-1] < v["v(m)"][-1]
    assert np.ptp(v["v(out)"][-1000:]) < 1e-6


@pytest.mark.parametrize("setting", [-20, -40, -50, -70, -80])
def test_gain_follows_the_labels(neve, setting):
    pytest.importorskip("circuitsim")
    g, _ = _run(neve, {"sensitivity": setting})
    assert g == pytest.approx(-setting, abs=1.5)  # the profile: -55 is 53.6, -70 68.9


def test_lo_is_hotter_and_the_top_end(neve):
    pytest.importorskip("circuitsim")
    hi, _ = _run(neve, {"sensitivity": -50})
    lo, _ = _run(neve, {"sensitivity": -50, "impedance": 0})
    assert 3.0 < lo - hi < 6.5  # 1:4 against 1:2, less the heavier loading
    hf, _ = _run(neve, {"sensitivity": -50}, f_hz=20000.0, dur_s=0.1)
    assert -0.8 < hf - hi < -0.2
